const meta=await api.spreadsheets.get({spreadsheetId:sid,fields:"sheets.properties"}); const existing=new Set((meta.data.sheets||[]).map(s=>s.properties?.title));
const missing=Object.keys(schema).filter(n=>!existing.has(n)); if(missing.length)await api.spreadsheets.batchUpdate({spreadsheetId:sid,requestBody:{requests:missing.map(title=>({addSheet:{properties:{title}}}))}});
for(const [name,headers] of Object.entries(schema)){const r=await api.spreadsheets.values.get({spreadsheetId:sid,range:`'${name}'!1:1`});const current=(r.data.values?.[0]||[]).map(String);if(!current.length)await api.spreadsheets.values.update({spreadsheetId:sid,range:`'${name}'!A1`,valueInputOption:"RAW",requestBody:{values:[headers]}});else{const merged=[...current,...headers.filter(h=>!current.includes(h))];if(merged.length!==current.length)await api.spreadsheets.values.update({spreadsheetId:sid,range:`'${name}'!A1`,valueInputOption:"RAW",requestBody:{values:[merged]}})}}
async function rows(name){const r=await api.spreadsheets.values.get({spreadsheetId:sid,range:`'${name}'`});const v=r.data.values||[];const h=v[0]||[];return v.slice(1).map(row=>Object.fromEntries(h.map((x,i)=>[x,row[i]??""])))}
async function append(name,obj){const r=await api.spreadsheets.values.get({spreadsheetId:sid,range:`'${name}'!1:1`});const headers=(r.data.values?.[0]||schema[name]).map(String);await api.spreadsheets.values.append({spreadsheetId:sid,range:`'${name}'!A1`,valueInputOption:"RAW",insertDataOption:"INSERT_ROWS",requestBody:{values:[headers.map(h=>obj[h]??"")]}})}
